-- Transactional webhook outbox with server-only endpoint and signing secrets.
create table if not exists public.cms_webhook_automations(id uuid primary key default gen_random_uuid(),name text not null,event_keys text[] not null,endpoint_ref text not null,enabled boolean not null default false,max_attempts integer not null default 5 check(max_attempts between 1 and 10),created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.cms_webhook_deliveries(id uuid primary key default gen_random_uuid(),automation_id uuid not null references public.cms_webhook_automations(id) on delete cascade,event_key text not null,event_id uuid,payload jsonb not null,status text not null default 'pending' check(status in('pending','running','delivered','retrying','failed','cancelled')),attempt_count integer not null default 0,next_attempt_at timestamptz not null default now(),claimed_at timestamptz,completed_at timestamptz,http_status integer,response_excerpt text,error_message text,created_at timestamptz not null default now());
create index if not exists cms_webhook_delivery_queue_idx on public.cms_webhook_deliveries(status,next_attempt_at);
alter table public.cms_webhook_automations enable row level security;alter table public.cms_webhook_deliveries enable row level security;grant select on public.cms_webhook_automations,public.cms_webhook_deliveries to authenticated;create policy "CMS reads webhook automations" on public.cms_webhook_automations for select to authenticated using(public.cms_current_role()='super_admin');create policy "CMS reads webhook deliveries" on public.cms_webhook_deliveries for select to authenticated using(public.cms_current_role()='super_admin');
create or replace function public.cms_save_webhook_automation(p_id uuid,p_name text,p_event_keys text[],p_endpoint_ref text,p_enabled boolean,p_max_attempts integer)returns public.cms_webhook_automations language plpgsql security definer set search_path=public as $$ declare v public.cms_webhook_automations;begin if public.cms_current_role()<>'super_admin'then raise exception 'permission_denied';end if;if trim(p_name)=''or p_endpoint_ref!~'^[a-z0-9_-]{2,50}$'or cardinality(p_event_keys)<1 or p_max_attempts not between 1 and 10 then raise exception 'invalid_automation';end if;if exists(select 1 from unnest(p_event_keys)x where x not in('published','inquiry_created','review_requested','translation_approved','release_completed','quality_failed','integration_failed','backup_failed','*'))then raise exception 'unsupported_event';end if;if p_id is null then insert into public.cms_webhook_automations(name,event_keys,endpoint_ref,enabled,max_attempts,created_by,updated_by)values(trim(p_name),p_event_keys,p_endpoint_ref,p_enabled,p_max_attempts,auth.uid(),auth.uid())returning * into v;else update public.cms_webhook_automations set name=trim(p_name),event_keys=p_event_keys,endpoint_ref=p_endpoint_ref,enabled=p_enabled,max_attempts=p_max_attempts,updated_by=auth.uid(),updated_at=now()where id=p_id returning * into v;if not found then raise exception 'automation_not_found';end if;end if;insert into public.cms_audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'webhook_automation_saved','webhook_automation',v.id::text,jsonb_build_object('enabled',v.enabled,'endpoint_ref',v.endpoint_ref));return v;end $$;
create or replace function public.cms_test_webhook_automation(p_id uuid)returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;begin if public.cms_current_role()<>'super_admin'then raise exception 'permission_denied';end if;insert into public.cms_webhook_deliveries(automation_id,event_key,payload)select id,'test',jsonb_build_object('schema_version',1,'event','test','occurred_at',now(),'automation_id',id)from public.cms_webhook_automations where id=p_id returning id into v_id;if v_id is null then raise exception 'automation_not_found';end if;return v_id;end $$;
create or replace function public.cms_enqueue_webhooks()returns trigger language plpgsql security definer set search_path=public as $$ declare v_event text:=case when new.action='submitted'then'review_requested'else new.action end;begin insert into public.cms_webhook_deliveries(automation_id,event_key,event_id,payload)select a.id,v_event,new.id,jsonb_build_object('schema_version',1,'event',v_event,'event_id',new.id,'occurred_at',new.created_at,'resource_type',new.resource_type,'resource_id',new.resource_id,'metadata',new.metadata)from public.cms_webhook_automations a where a.enabled and(v_event=any(a.event_keys)or'*'=any(a.event_keys));return new;end $$;
drop trigger if exists cms_audit_webhook_outbox on public.cms_audit_logs;create trigger cms_audit_webhook_outbox after insert on public.cms_audit_logs for each row execute function public.cms_enqueue_webhooks();
create or replace function public.cms_enqueue_inquiry_webhooks()returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.cms_webhook_deliveries(automation_id,event_key,event_id,payload)select a.id,'inquiry_created',new.id,jsonb_build_object('schema_version',1,'event','inquiry_created','event_id',new.id,'occurred_at',new.created_at,'source',new.source,'language',new.language)from public.cms_webhook_automations a where a.enabled and('inquiry_created'=any(a.event_keys)or'*'=any(a.event_keys));return new;end $$;
drop trigger if exists cms_inquiry_webhook_outbox on public.cms_inquiries;create trigger cms_inquiry_webhook_outbox after insert on public.cms_inquiries for each row execute function public.cms_enqueue_inquiry_webhooks();
create or replace function public.cms_claim_webhook_deliveries(p_limit integer default 20)returns table(id uuid,endpoint_ref text,payload jsonb,attempt_count integer,max_attempts integer)language plpgsql security definer set search_path=public as $$ begin if auth.role()<>'service_role'then raise exception 'service_role_required';end if;return query with claimed as(select d.id from public.cms_webhook_deliveries d where d.status in('pending','retrying')and d.next_attempt_at<=now() order by d.created_at for update skip locked limit least(greatest(p_limit,1),100))update public.cms_webhook_deliveries d set status='running',claimed_at=now(),attempt_count=d.attempt_count+1 from claimed c,public.cms_webhook_automations a where d.id=c.id and a.id=d.automation_id returning d.id,a.endpoint_ref,d.payload,d.attempt_count,a.max_attempts;end $$;
create or replace function public.cms_record_webhook_delivery(p_id uuid,p_delivered boolean,p_http_status integer,p_excerpt text,p_error text)returns void language plpgsql security definer set search_path=public as $$ declare v_attempt integer;v_max integer;begin if auth.role()<>'service_role'then raise exception 'service_role_required';end if;select d.attempt_count,a.max_attempts into v_attempt,v_max from public.cms_webhook_deliveries d join public.cms_webhook_automations a on a.id=d.automation_id where d.id=p_id and d.status='running'for update;if not found then raise exception 'delivery_not_running';end if;update public.cms_webhook_deliveries set status=case when p_delivered then'delivered'when v_attempt>=v_max then'failed'else'retrying'end,completed_at=case when p_delivered or v_attempt>=v_max then now()else null end,next_attempt_at=case when p_delivered then next_attempt_at else now()+make_interval(secs=>least(3600,30*power(2,v_attempt-1)::integer))end,http_status=p_http_status,response_excerpt=left(p_excerpt,300),error_message=left(p_error,500)where id=p_id;end $$;
revoke execute on function public.cms_save_webhook_automation(uuid,text,text[],text,boolean,integer),public.cms_test_webhook_automation(uuid),public.cms_claim_webhook_deliveries(integer),public.cms_record_webhook_delivery(uuid,boolean,integer,text,text) from public,anon;grant execute on function public.cms_save_webhook_automation(uuid,text,text[],text,boolean,integer),public.cms_test_webhook_automation(uuid) to authenticated;grant execute on function public.cms_claim_webhook_deliveries(integer),public.cms_record_webhook_delivery(uuid,boolean,integer,text,text) to service_role;
